const std = @import("std");
const Allocator = std.mem.Allocator;

pub const PartWholeTree = struct {
    allocator: Allocator,
    nodes: std.ArrayList(TreeNode),
    root: ?u32,
    max_depth: u32,

    pub const TreeNode = struct {
        id: u32,
        parent: ?u32,
        children: std.ArrayList(u32),
        part_code: u64,
        whole_code: u64,
        depth: u32,
        is_leaf: bool,

        pub fn init(allocator: Allocator, id: u32, depth: u32) TreeNode {
            return TreeNode{
                .id = id,
                .parent = null,
                .children = std.ArrayList(u32).init(allocator),
                .part_code = 0,
                .whole_code = 0,
                .depth = depth,
                .is_leaf = true,
            };
        }

        pub fn deinit(self: *TreeNode) void {
            self.children.deinit();
        }
    };

    pub fn init(allocator: Allocator) PartWholeTree {
        return PartWholeTree{
            .allocator = allocator,
            .nodes = std.ArrayList(TreeNode).init(allocator),
            .root = null,
            .max_depth = 0,
        };
    }

    pub fn deinit(self: *PartWholeTree) void {
        for (self.nodes.items) |*node| {
            node.deinit();
        }
        self.nodes.deinit();
    }

    pub fn addNode(self: *PartWholeTree, parent: ?u32, depth: u32) !u32 {
        const id = @as(u32, @intCast(self.nodes.items.len));
        var node = TreeNode.init(self.allocator, id, depth);
        node.parent = parent;

        try self.nodes.append(node);

        if (parent) |p_id| {
            self.nodes.items[p_id].is_leaf = false;
            try self.nodes.items[p_id].children.append(id);
        } else {
            self.root = id;
        }

        if (depth > self.max_depth) {
            self.max_depth = depth;
        }

        return id;
    }

    pub fn computeWholeCodes(self: *PartWholeTree) void {
        if (self.root) |root_id| {
            self.computeWholeCodesRecursive(root_id);
        }
    }

    fn computeWholeCodesRecursive(self: *PartWholeTree, node_id: u32) u64 {
        var node = &self.nodes.items[node_id];

        if (node.is_leaf) {
            node.whole_code = node.part_code;
            return node.whole_code;
        }

        var combined: u64 = node.part_code;
        for (node.children.items) |child_id| {
            const child_whole = self.computeWholeCodesRecursive(child_id);
            combined ^= child_whole;
        }

        node.whole_code = combined;
        return combined;
    }

    pub fn propagateToLeaves(self: *PartWholeTree, node_id: u32, code: u64) void {
        var node = &self.nodes.items[node_id];
        node.part_code ^= code;

        for (node.children.items) |child_id| {
            self.propagateToLeaves(child_id, code);
        }
    }

    pub fn findCommonAncestor(self: *PartWholeTree, node1: u32, node2: u32) ?u32 {
        var ancestors1 = std.ArrayList(u32).init(self.allocator);
        defer ancestors1.deinit();

        var current = node1;
        while (true) {
            ancestors1.append(current) catch break;
            if (self.nodes.items[current].parent) |p| {
                current = p;
            } else {
                break;
            }
        }

        current = node2;
        while (true) {
            for (ancestors1.items) |anc| {
                if (current == anc) {
                    return current;
                }
            }
            if (self.nodes.items[current].parent) |p| {
                current = p;
            } else {
                break;
            }
        }

        return null;
    }
};

pub const AbductiveReasoner = struct {
    allocator: Allocator,
    tree: PartWholeTree,
    inference_cache: std.AutoHashMap(u64, u32),

    pub fn init(allocator: Allocator) AbductiveReasoner {
        return AbductiveReasoner{
            .allocator = allocator,
            .tree = PartWholeTree.init(allocator),
            .inference_cache = std.AutoHashMap(u64, u32).init(allocator),
        };
    }

    pub fn deinit(self: *AbductiveReasoner) void {
        self.tree.deinit();
        self.inference_cache.deinit();
    }

    pub fn abduce(self: *AbductiveReasoner, observation: u64) !?u32 {
        if (self.inference_cache.get(observation)) |cached| {
            return cached;
        }

        var best_node: ?u32 = null;
        var min_distance: u32 = std.math.maxInt(u32);

        for (self.tree.nodes.items, 0..) |node, idx| {
            const distance = @popCount(observation ^ node.whole_code);
            if (distance < min_distance) {
                min_distance = distance;
                best_node = @as(u32, @intCast(idx));
            }
        }

        if (best_node) |bn| {
            try self.inference_cache.put(observation, bn);
        }

        return best_node;
    }

    pub fn explainObservation(self: *AbductiveReasoner, observation: u64, path: *std.ArrayList(u32)) !void {
        if (try self.abduce(observation)) |node_id| {
            var current = node_id;
            try path.append(current);

            while (self.tree.nodes.items[current].parent) |parent_id| {
                try path.append(parent_id);
                current = parent_id;
            }
        }
    }

    pub fn induceHypothesis(self: *AbductiveReasoner, observations: []const u64) !u64 {
        var hypothesis: u64 = 0;

        for (observations) |obs| {
            if (try self.abduce(obs)) |node_id| {
                hypothesis ^= self.tree.nodes.items[node_id].whole_code;
            }
        }

        return hypothesis;
    }
};

pub const HierarchicalEncoder = struct {
    allocator: Allocator,
    layers: std.ArrayList(EncoderLayer),
    tree_structure: PartWholeTree,

    pub const EncoderLayer = struct {
        input_size: usize,
        output_size: usize,
        codes: []u64,
        parent_mappings: []u32,
        allocator: Allocator,

        pub fn init(allocator: Allocator, input_size: usize, output_size: usize) !EncoderLayer {
            const codes = try allocator.alloc(u64, output_size);
            const parent_mappings = try allocator.alloc(u32, output_size);

            var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
            const random = prng.random();

            for (codes) |*c| {
                c.* = random.int(u64);
            }

            for (parent_mappings, 0..) |*p, i| {
                p.* = @as(u32, @intCast(i % (output_size / 2)));
            }

            return EncoderLayer{
                .input_size = input_size,
                .output_size = output_size,
                .codes = codes,
                .parent_mappings = parent_mappings,
                .allocator = allocator,
            };
        }

        pub fn deinit(self: *EncoderLayer) void {
            self.allocator.free(self.codes);
            self.allocator.free(self.parent_mappings);
        }

        pub fn encode(self: *EncoderLayer, input: []const u64, output: []u64) void {
            for (0..self.output_size) |i| {
                var accumulated: u64 = 0;
                const window_size = self.input_size / self.output_size;
                const start = i * window_size;
                const end = @min(start + window_size, self.input_size);

                for (input[start..end]) |val| {
                    accumulated ^= val;
                }

                output[i] = accumulated ^ self.codes[i];
            }
        }
    };

    pub fn init(allocator: Allocator) HierarchicalEncoder {
        return HierarchicalEncoder{
            .allocator = allocator,
            .layers = std.ArrayList(EncoderLayer).init(allocator),
            .tree_structure = PartWholeTree.init(allocator),
        };
    }

    pub fn deinit(self: *HierarchicalEncoder) void {
        for (self.layers.items) |*layer| {
            layer.deinit();
        }
        self.layers.deinit();
        self.tree_structure.deinit();
    }

    pub fn addLayer(self: *HierarchicalEncoder, input_size: usize, output_size: usize) !void {
        const layer = try EncoderLayer.init(self.allocator, input_size, output_size);
        try self.layers.append(layer);
    }

    pub fn encodeHierarchical(self: *HierarchicalEncoder, input: []const u64, output: *std.ArrayList(u64)) !void {
        if (self.layers.items.len == 0) return;

        var current_input = input;
        var temp_buffer = try self.allocator.alloc(u64, 1024);
        defer self.allocator.free(temp_buffer);

        for (self.layers.items) |*layer| {
            const layer_output = temp_buffer[0..layer.output_size];
            layer.encode(current_input, layer_output);

            try output.appendSlice(layer_output);
            current_input = layer_output;
        }
    }

    pub fn buildTreeFromHierarchy(self: *HierarchicalEncoder) !void {
        const root = try self.tree_structure.addNode(null, 0);

        var prev_layer_nodes = try self.allocator.alloc(u32, 1);
        defer self.allocator.free(prev_layer_nodes);
        prev_layer_nodes[0] = root;

        for (self.layers.items, 1..) |*layer, depth| {
            const curr_layer_nodes = try self.allocator.alloc(u32, layer.output_size);
            defer self.allocator.free(curr_layer_nodes);

            for (0..layer.output_size) |i| {
                const parent_idx = layer.parent_mappings[i] % prev_layer_nodes.len;
                const node_id = try self.tree_structure.addNode(prev_layer_nodes[parent_idx], @as(u32, @intCast(depth)));
                curr_layer_nodes[i] = node_id;
                self.tree_structure.nodes.items[node_id].part_code = layer.codes[i];
            }

            const new_prev = try self.allocator.alloc(u32, curr_layer_nodes.len);
            @memcpy(new_prev, curr_layer_nodes);
            self.allocator.free(prev_layer_nodes);
            prev_layer_nodes = new_prev;
        }

        self.tree_structure.computeWholeCodes();
    }
};

pub const PositionalEncoder = struct {
    allocator: Allocator,
    max_sequence_length: usize,
    dimension: usize,
    position_codes: []u64,

    pub fn init(allocator: Allocator, max_seq_len: usize, dim: usize) !PositionalEncoder {
        const codes = try allocator.alloc(u64, max_seq_len * dim);

        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (0..max_seq_len) |pos| {
            for (0..dim) |d| {
                const idx = pos * dim + d;
                const angle: f64 = @as(f64, @floatFromInt(pos)) / std.math.pow(f64, 10000.0, @as(f64, @floatFromInt(2 * d)) / @as(f64, @floatFromInt(dim)));
                const sin_val = @sin(angle);
                const scaled = @as(u64, @intFromFloat(@abs(sin_val) * @as(f64, @floatFromInt(std.math.maxInt(u64)))));
                codes[idx] = scaled ^ random.int(u64);
            }
        }

        return PositionalEncoder{
            .allocator = allocator,
            .max_sequence_length = max_seq_len,
            .dimension = dim,
            .position_codes = codes,
        };
    }

    pub fn deinit(self: *PositionalEncoder) void {
        self.allocator.free(self.position_codes);
    }

    pub fn encode(self: *PositionalEncoder, sequence: []const u64, positions: []const usize, output: []u64) void {
        for (positions, 0..) |pos, i| {
            if (pos < self.max_sequence_length and i < sequence.len) {
                const base_idx = pos * self.dimension;
                for (0..self.dimension) |d| {
                    if (base_idx + d < self.position_codes.len and i < output.len) {
                        output[i] = sequence[i] ^ self.position_codes[base_idx + d];
                    }
                }
            }
        }
    }

    pub fn encodeRelativePositions(self: *PositionalEncoder, pos1: usize, pos2: usize) u64 {
        if (pos1 >= self.max_sequence_length or pos2 >= self.max_sequence_length) {
            return 0;
        }

        var result: u64 = 0;
        const idx1 = pos1 * self.dimension;
        const idx2 = pos2 * self.dimension;

        for (0..self.dimension) |d| {
            if (idx1 + d < self.position_codes.len and idx2 + d < self.position_codes.len) {
                result ^= self.position_codes[idx1 + d] ^ self.position_codes[idx2 + d];
            }
        }

        return result;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var reasoner = AbductiveReasoner.init(allocator);
    defer reasoner.deinit();

    _ = try reasoner.tree.addNode(null, 0);
    for (0..10) |i| {
        _ = try reasoner.tree.addNode(0, 1);
        for (0..5) |j| {
            const child = @as(u32, @intCast(i * 5 + j + 1));
            _ = try reasoner.tree.addNode(child, 2);
        }
    }

    reasoner.tree.computeWholeCodes();

    const observation: u64 = 0x123456789ABCDEF0;
    if (try reasoner.abduce(observation)) |node_id| {
        std.debug.print("Best match node: {}\n", .{node_id});
    }

    var encoder = HierarchicalEncoder.init(allocator);
    defer encoder.deinit();

    try encoder.addLayer(256, 128);
    try encoder.addLayer(128, 64);
    try encoder.addLayer(64, 32);

    const input = try allocator.alloc(u64, 256);
    defer allocator.free(input);

    var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
    const random = prng.random();

    for (input) |*val| {
        val.* = random.int(u64);
    }

    var output = std.ArrayList(u64).init(allocator);
    defer output.deinit();

    try encoder.encodeHierarchical(input, &output);
    try encoder.buildTreeFromHierarchy();

    var pos_encoder = try PositionalEncoder.init(allocator, 512, 64);
    defer pos_encoder.deinit();

    const seq = try allocator.alloc(u64, 100);
    defer allocator.free(seq);
    const positions = try allocator.alloc(usize, 100);
    defer allocator.free(positions);
    const pos_output = try allocator.alloc(u64, 100);
    defer allocator.free(pos_output);

    for (seq, 0..) |*s, i| {
        s.* = random.int(u64);
        positions[i] = i;
    }

    pos_encoder.encode(seq, positions, pos_output);
}
