const std = @import("std");
const Allocator = std.mem.Allocator;

pub const EnergyFunction = struct {
    pub fn hamiltonianEnergy(state: []const u64, interactions: []const Interaction) f64 {
        var total_energy: f64 = 0.0;

        for (interactions) |interaction| {
            const i = interaction.site1;
            const j = interaction.site2;

            if (i < state.len and j < state.len) {
                const coupling = interaction.strength;
                const xor_bits = state[i] ^ state[j];
                const bit_diff = @as(f64, @floatFromInt(@popCount(xor_bits)));
                total_energy += coupling * bit_diff;
            }
        }

        return total_energy;
    }

    pub fn isingEnergy(spins: []const i8, couplings: []const f64, field: f64) f64 {
        var energy: f64 = 0.0;

        for (spins, 0..) |spin, i| {
            energy -= field * @as(f64, @floatFromInt(spin));

            if (i + 1 < spins.len) {
                const idx = i;
                if (idx < couplings.len) {
                    energy -= couplings[idx] * @as(f64, @floatFromInt(spin * spins[i + 1]));
                }
            }
        }

        return energy;
    }

    pub fn computeLocalEnergy(state: []const u64, site: usize, neighbors: []const usize, strengths: []const f64) f64 {
        if (site >= state.len) return 0.0;

        var local_energy: f64 = 0.0;

        for (neighbors, 0..) |neighbor, idx| {
            if (neighbor < state.len and idx < strengths.len) {
                const xor_result = state[site] ^ state[neighbor];
                const bit_count = @as(f64, @floatFromInt(@popCount(xor_result)));
                local_energy += strengths[idx] * bit_count;
            }
        }

        return local_energy;
    }
};

pub const Interaction = struct {
    site1: usize,
    site2: usize,
    strength: f64,
};

pub const GroundStateFinder = struct {
    allocator: Allocator,
    state_space_size: usize,
    interactions: std.ArrayList(Interaction),
    current_state: []u64,
    best_state: []u64,
    best_energy: f64,
    temperature: f64,

    pub fn init(allocator: Allocator, size: usize) !GroundStateFinder {
        const current = try allocator.alloc(u64, size);
        const best = try allocator.alloc(u64, size);

        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (current) |*c| {
            c.* = random.int(u64);
        }
        @memcpy(best, current);

        return GroundStateFinder{
            .allocator = allocator,
            .state_space_size = size,
            .interactions = std.ArrayList(Interaction).init(allocator),
            .current_state = current,
            .best_state = best,
            .best_energy = std.math.floatMax(f64),
            .temperature = 1.0,
        };
    }

    pub fn deinit(self: *GroundStateFinder) void {
        self.allocator.free(self.current_state);
        self.allocator.free(self.best_state);
        self.interactions.deinit();
    }

    pub fn addInteraction(self: *GroundStateFinder, site1: usize, site2: usize, strength: f64) !void {
        try self.interactions.append(Interaction{
            .site1 = site1,
            .site2 = site2,
            .strength = strength,
        });
    }

    pub fn simulatedAnnealing(self: *GroundStateFinder, iterations: usize, cooling_rate: f64) !void {
        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        self.temperature = 1.0;
        var current_energy = EnergyFunction.hamiltonianEnergy(self.current_state, self.interactions.items);
        self.best_energy = current_energy;
        @memcpy(self.best_state, self.current_state);

        for (0..iterations) |_| {
            const flip_site = random.intRangeLessThan(usize, 0, self.state_space_size);
            const flip_bit = random.intRangeLessThan(u6, 0, 64);

            self.current_state[flip_site] ^= @as(u64, 1) << flip_bit;

            const new_energy = EnergyFunction.hamiltonianEnergy(self.current_state, self.interactions.items);
            const delta_energy = new_energy - current_energy;

            const accept = if (delta_energy < 0) true else blk: {
                const prob = @exp(-delta_energy / self.temperature);
                break :blk random.float(f64) < prob;
            };

            if (accept) {
                current_energy = new_energy;
                if (new_energy < self.best_energy) {
                    self.best_energy = new_energy;
                    @memcpy(self.best_state, self.current_state);
                }
            } else {
                self.current_state[flip_site] ^= @as(u64, 1) << flip_bit;
            }

            self.temperature *= cooling_rate;
        }
    }

    pub fn quantumAnnealing(self: *GroundStateFinder, iterations: usize, transverse_field_schedule: []const f64) !void {
        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (0..iterations) |iter| {
            const field_strength = if (iter < transverse_field_schedule.len)
                transverse_field_schedule[iter]
            else
                0.0;

            for (0..self.state_space_size) |site| {
                if (random.float(f64) < field_strength) {
                    const flip_bit = random.intRangeLessThan(u6, 0, 64);
                    self.current_state[site] ^= @as(u64, 1) << flip_bit;
                }
            }

            const current_energy = EnergyFunction.hamiltonianEnergy(self.current_state, self.interactions.items);

            if (current_energy < self.best_energy) {
                self.best_energy = current_energy;
                @memcpy(self.best_state, self.current_state);
            }
        }
    }

    pub fn variationalOptimization(self: *GroundStateFinder, learning_rate: f64, steps: usize) !void {
        var params = try self.allocator.alloc(f64, self.state_space_size * 64);
        defer self.allocator.free(params);

        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (params) |*p| {
            p.* = random.float(f64) * 2.0 - 1.0;
        }

        for (0..steps) |_| {
            for (0..self.state_space_size) |site| {
                for (0..64) |bit| {
                    const param_idx = site * 64 + bit;
                    const original_value = params[param_idx];

                    params[param_idx] += 0.001;
                    const state_plus = self.paramsToState(params);
                    const energy_plus = EnergyFunction.hamiltonianEnergy(state_plus, self.interactions.items);
                    self.allocator.free(state_plus);

                    params[param_idx] = original_value - 0.001;
                    const state_minus = self.paramsToState(params);
                    const energy_minus = EnergyFunction.hamiltonianEnergy(state_minus, self.interactions.items);
                    self.allocator.free(state_minus);

                    const gradient = (energy_plus - energy_minus) / 0.002;
                    params[param_idx] = original_value - learning_rate * gradient;
                }
            }

            const new_state = self.paramsToState(params);
            const new_energy = EnergyFunction.hamiltonianEnergy(new_state, self.interactions.items);

            if (new_energy < self.best_energy) {
                self.best_energy = new_energy;
                @memcpy(self.best_state, new_state);
            }

            self.allocator.free(new_state);
        }
    }

    fn paramsToState(self: *GroundStateFinder, params: []const f64) []u64 {
        const state = self.allocator.alloc(u64, self.state_space_size) catch unreachable;

        for (0..self.state_space_size) |site| {
            var bits: u64 = 0;
            for (0..64) |bit| {
                const param_idx = site * 64 + bit;
                if (param_idx < params.len and params[param_idx] > 0) {
                    bits |= @as(u64, 1) << @intCast(bit);
                }
            }
            state[site] = bits;
        }

        return state;
    }
};

pub const ConstraintPropagator = struct {
    allocator: Allocator,
    num_variables: usize,
    domains: []std.ArrayList(u64),
    constraints: std.ArrayList(Constraint),

    pub const Constraint = struct {
        var1: usize,
        var2: usize,
        relation: u64,
        weight: f64,
    };

    pub fn init(allocator: Allocator, num_vars: usize) !ConstraintPropagator {
        const domains = try allocator.alloc(std.ArrayList(u64), num_vars);

        for (domains) |*domain| {
            domain.* = std.ArrayList(u64).init(allocator);
        }

        return ConstraintPropagator{
            .allocator = allocator,
            .num_variables = num_vars,
            .domains = domains,
            .constraints = std.ArrayList(Constraint).init(allocator),
        };
    }

    pub fn deinit(self: *ConstraintPropagator) void {
        for (self.domains) |*domain| {
            domain.deinit();
        }
        self.allocator.free(self.domains);
        self.constraints.deinit();
    }

    pub fn addConstraint(self: *ConstraintPropagator, var1: usize, var2: usize, relation: u64, weight: f64) !void {
        try self.constraints.append(Constraint{
            .var1 = var1,
            .var2 = var2,
            .relation = relation,
            .weight = weight,
        });
    }

    pub fn initializeDomains(self: *ConstraintPropagator, values: []const u64) !void {
        for (self.domains, 0..) |*domain, i| {
            if (i < values.len) {
                try domain.append(values[i]);
            }
        }
    }

    pub fn propagate(self: *ConstraintPropagator) !bool {
        var changed = true;
        var iterations: usize = 0;
        const max_iterations: usize = 1000;

        while (changed and iterations < max_iterations) {
            changed = false;
            iterations += 1;

            for (self.constraints.items) |constraint| {
                const var1 = constraint.var1;
                const var2 = constraint.var2;

                if (var1 >= self.num_variables or var2 >= self.num_variables) continue;

                var new_domain1 = std.ArrayList(u64).init(self.allocator);
                defer new_domain1.deinit();

                for (self.domains[var1].items) |val1| {
                    var has_support = false;
                    for (self.domains[var2].items) |val2| {
                        const combined = val1 ^ val2;
                        if (@popCount(combined ^ constraint.relation) < 16) {
                            has_support = true;
                            break;
                        }
                    }
                    if (has_support) {
                        try new_domain1.append(val1);
                    }
                }

                if (new_domain1.items.len < self.domains[var1].items.len) {
                    self.domains[var1].clearRetainingCapacity();
                    try self.domains[var1].appendSlice(new_domain1.items);
                    changed = true;
                }
            }
        }

        for (self.domains) |domain| {
            if (domain.items.len == 0) {
                return false;
            }
        }

        return true;
    }

    pub fn extractSolution(self: *ConstraintPropagator, solution: []u64) void {
        for (self.domains, 0..) |domain, i| {
            if (i < solution.len and domain.items.len > 0) {
                solution[i] = domain.items[0];
            }
        }
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var finder = try GroundStateFinder.init(allocator, 50);
    defer finder.deinit();

    for (0..50) |i| {
        for (i + 1..50) |j| {
            const strength = -1.0;
            try finder.addInteraction(i, j, strength);
        }
    }

    try finder.simulatedAnnealing(10000, 0.995);
    std.debug.print("Best energy found (SA): {d:.6}\n", .{finder.best_energy});

    const field_schedule = try allocator.alloc(f64, 1000);
    defer allocator.free(field_schedule);

    for (field_schedule, 0..) |*f, i| {
        f.* = 1.0 - @as(f64, @floatFromInt(i)) / 1000.0;
    }

    try finder.quantumAnnealing(1000, field_schedule);
    std.debug.print("Best energy found (QA): {d:.6}\n", .{finder.best_energy});

    var propagator = try ConstraintPropagator.init(allocator, 20);
    defer propagator.deinit();

    const initial_values = try allocator.alloc(u64, 20);
    defer allocator.free(initial_values);

    var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
    const random = prng.random();

    for (initial_values) |*v| {
        v.* = random.int(u64);
    }

    try propagator.initializeDomains(initial_values);

    for (0..20) |i| {
        if (i + 1 < 20) {
            try propagator.addConstraint(i, i + 1, 0xAAAAAAAAAAAAAAAA, 1.0);
        }
    }

    const success = try propagator.propagate();
    std.debug.print("Constraint propagation: {}\n", .{success});

    const solution = try allocator.alloc(u64, 20);
    defer allocator.free(solution);
    propagator.extractSolution(solution);
}
