const std = @import("std");
const Allocator = std.mem.Allocator;

pub const BitwiseAttentionMechanism = struct {
    allocator: Allocator,
    num_heads: usize,
    head_dim: usize,
    query_proj: []u64,
    key_proj: []u64,
