    pub fn init(allocator: Allocator, num_heads: usize, head_dim: usize) !BitwiseAttentionMechanism {
        const total_dim = num_heads * head_dim;
        const query_proj = try allocator.alloc(u64, total_dim * total_dim);
        const key_proj = try allocator.alloc(u64, total_dim * total_dim);
        const value_proj = try allocator.alloc(u64, total_dim * total_dim);
        const output_proj = try allocator.alloc(u64, total_dim * total_dim);
        const attention_mask = try allocator.alloc(u8, total_dim);

        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (query_proj) |*qp| {
            qp.* = random.int(u64);
        }

        for (key_proj) |*kp| {
            kp.* = random.int(u64);
        }

        for (value_proj) |*vp| {
            vp.* = random.int(u64);
        }

        for (output_proj) |*op| {
            op.* = random.int(u64);
        }

        for (attention_mask) |*am| {
            am.* = 255;
        }

        return BitwiseAttentionMechanism{
            .allocator = allocator,
            .num_heads = num_heads,
            .head_dim = head_dim,
            .query_proj = query_proj,
            .key_proj = key_proj,
            .value_proj = value_proj,
            .output_proj = output_proj,
            .attention_mask = attention_mask,
        };
    }

    pub fn deinit(self: *BitwiseAttentionMechanism) void {
        self.allocator.free(self.query_proj);
        self.allocator.free(self.key_proj);
        self.allocator.free(self.value_proj);
        self.allocator.free(self.output_proj);
        self.allocator.free(self.attention_mask);
    }

    pub fn projectQuery(self: *BitwiseAttentionMechanism, input: []const u64, output: []u64) void {
        const total_dim = self.num_heads * self.head_dim;

        for (0..total_dim) |out_idx| {
            var accumulator: u64 = 0;

            for (0..total_dim) |in_idx| {
                const proj_idx = out_idx * total_dim + in_idx;
                if (proj_idx < self.query_proj.len and in_idx < input.len) {
                    accumulator ^= input[in_idx] & self.query_proj[proj_idx];
                }
            }

            if (out_idx < output.len) {
                output[out_idx] = accumulator;
            }
        }
    }

    pub fn projectKey(self: *BitwiseAttentionMechanism, input: []const u64, output: []u64) void {
        const total_dim = self.num_heads * self.head_dim;

        for (0..total_dim) |out_idx| {
            var accumulator: u64 = 0;

            for (0..total_dim) |in_idx| {
                const proj_idx = out_idx * total_dim + in_idx;
                if (proj_idx < self.key_proj.len and in_idx < input.len) {
                    accumulator ^= input[in_idx] & self.key_proj[proj_idx];
                }
            }

            if (out_idx < output.len) {
                output[out_idx] = accumulator;
            }
        }
    }

    pub fn projectValue(self: *BitwiseAttentionMechanism, input: []const u64, output: []u64) void {
        const total_dim = self.num_heads * self.head_dim;

        for (0..total_dim) |out_idx| {
            var accumulator: u64 = 0;

            for (0..total_dim) |in_idx| {
                const proj_idx = out_idx * total_dim + in_idx;
                if (proj_idx < self.value_proj.len and in_idx < input.len) {
                    accumulator ^= input[in_idx] & self.value_proj[proj_idx];
                }
            }

            if (out_idx < output.len) {
                output[out_idx] = accumulator;
            }
        }
    }

    pub fn computeBitwiseAttention(self: *BitwiseAttentionMechanism, queries: []const u64, keys: []const u64, values: []const u64, output: []u64, seq_len: usize) void {
        for (0..self.num_heads) |head_idx| {
            for (0..seq_len) |q_idx| {
                var attention_accumulator: u64 = 0;

                for (0..seq_len) |k_idx| {
                    const q_offset = head_idx * self.head_dim + q_idx * self.num_heads * self.head_dim;
                    const k_offset = head_idx * self.head_dim + k_idx * self.num_heads * self.head_dim;

                    var dot_product: u32 = 0;

                    for (0..self.head_dim) |dim| {
                        const q_pos = q_offset + dim;
                        const k_pos = k_offset + dim;

                        if (q_pos < queries.len and k_pos < keys.len) {
                            const qk_product = queries[q_pos] & keys[k_pos];
                            dot_product += @popCount(qk_product);
                        }
                    }

                    const attention_weight: u8 = @as(u8, @intCast(@min(dot_product, 255)));

                    if (attention_weight > 128) {
                        const v_offset = head_idx * self.head_dim + k_idx * self.num_heads * self.head_dim;

                        for (0..self.head_dim) |dim| {
                            const v_pos = v_offset + dim;
                            if (v_pos < values.len) {
                                attention_accumulator ^= values[v_pos];
                            }
                        }
                    }
                }

                const out_offset = head_idx * self.head_dim + q_idx * self.num_heads * self.head_dim;

                for (0..self.head_dim) |dim| {
                    const out_pos = out_offset + dim;
                    if (out_pos < output.len) {
                        output[out_pos] = attention_accumulator;
                    }
                }
            }
        }
    }

    pub fn forward(self: *BitwiseAttentionMechanism, input: []const u64, output: []u64, seq_len: usize) !void {
        const total_dim = self.num_heads * self.head_dim;

        const queries = try self.allocator.alloc(u64, total_dim * seq_len);
        defer self.allocator.free(queries);

        const keys = try self.allocator.alloc(u64, total_dim * seq_len);
        defer self.allocator.free(keys);

        const values = try self.allocator.alloc(u64, total_dim * seq_len);
        defer self.allocator.free(values);

        const attention_output = try self.allocator.alloc(u64, total_dim * seq_len);
        defer self.allocator.free(attention_output);

        for (0..seq_len) |seq_idx| {
            const input_offset = seq_idx * total_dim;
            const q_offset = seq_idx * total_dim;
            const k_offset = seq_idx * total_dim;
            const v_offset = seq_idx * total_dim;

            self.projectQuery(input[input_offset .. input_offset + total_dim], queries[q_offset .. q_offset + total_dim]);
            self.projectKey(input[input_offset .. input_offset + total_dim], keys[k_offset .. k_offset + total_dim]);
            self.projectValue(input[input_offset .. input_offset + total_dim], values[v_offset .. v_offset + total_dim]);
        }

        self.computeBitwiseAttention(queries, keys, values, attention_output, seq_len);

        for (0..seq_len) |seq_idx| {
            const attn_offset = seq_idx * total_dim;
            const out_offset = seq_idx * total_dim;

            for (0..total_dim) |dim| {
                var proj_accumulator: u64 = 0;

                for (0..total_dim) |in_dim| {
                    const proj_idx = dim * total_dim + in_dim;
                    const attn_idx = attn_offset + in_dim;

                    if (proj_idx < self.output_proj.len and attn_idx < attention_output.len) {
                        proj_accumulator ^= attention_output[attn_idx] & self.output_proj[proj_idx];
                    }
                }

                const final_idx = out_offset + dim;
                if (final_idx < output.len) {
                    output[final_idx] = proj_accumulator;
                }
            }
        }
    }
};

pub const BitwiseFeedForward = struct {
    allocator: Allocator,
    input_dim: usize,
    hidden_dim: usize,
    fc1_weights: []u64,
    fc2_weights: []u64,
    activation_threshold: u32,

    pub fn init(allocator: Allocator, input_dim: usize, hidden_dim: usize) !BitwiseFeedForward {
        const fc1_weights = try allocator.alloc(u64, input_dim * hidden_dim);
        const fc2_weights = try allocator.alloc(u64, hidden_dim * input_dim);

        var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const random = prng.random();

        for (fc1_weights) |*w| {
            w.* = random.int(u64);
        }

        for (fc2_weights) |*w| {
            w.* = random.int(u64);
        }

        return BitwiseFeedForward{
            .allocator = allocator,
            .input_dim = input_dim,
            .hidden_dim = hidden_dim,
            .fc1_weights = fc1_weights,
            .fc2_weights = fc2_weights,
            .activation_threshold = 32,
        };
    }

    pub fn deinit(self: *BitwiseFeedForward) void {
        self.allocator.free(self.fc1_weights);
        self.allocator.free(self.fc2_weights);
    }

    pub fn bitwiseActivation(self: *BitwiseFeedForward, input: u64) u64 {
        const pop_count = @popCount(input);

        if (pop_count > self.activation_threshold) {
            return input;
        } else {
            return ~input;
        }
    }

    pub fn forward(self: *BitwiseFeedForward, input: []const u64, output: []u64) void {
        const hidden = self.allocator.alloc(u64, self.hidden_dim) catch return;
        defer self.allocator.free(hidden);

        for (0..self.hidden_dim) |h_idx| {
            var accumulator: u64 = 0;

            for (0..self.input_dim) |in_idx| {
                const weight_idx = h_idx * self.input_dim + in_idx;
                if (weight_idx < self.fc1_weights.len and in_idx < input.len) {
                    accumulator ^= input[in_idx] & self.fc1_weights[weight_idx];
                }
            }

            hidden[h_idx] = self.bitwiseActivation(accumulator);
        }

        for (0..self.input_dim) |out_idx| {
            var accumulator: u64 = 0;

            for (0..self.hidden_dim) |h_idx| {
                const weight_idx = out_idx * self.hidden_dim + h_idx;
                if (weight_idx < self.fc2_weights.len) {
                    accumulator ^= hidden[h_idx] & self.fc2_weights[weight_idx];
                }
            }

            if (out_idx < output.len) {
                output[out_idx] = accumulator;
            }
        }
    }
};

pub const HamiltonianTransformerBlock = struct {
