    norm_scale: []u8,

    pub fn init(allocator: Allocator, dim: usize, num_heads: usize, ff_hidden_dim: usize) !HamiltonianTransformerBlock {
        const head_dim = dim / num_heads;
        const attention = try BitwiseAttentionMechanism.init(allocator, num_heads, head_dim);
        const feedforward = try BitwiseFeedForward.init(allocator, dim, ff_hidden_dim);
        const norm_scale = try allocator.alloc(u8, dim);

        for (norm_scale) |*ns| {
            ns.* = 128;
        }

        return HamiltonianTransformerBlock{
            .allocator = allocator,
            .attention = attention,
            .feedforward = feedforward,
            .norm_scale = norm_scale,
        };
    }

    pub fn deinit(self: *HamiltonianTransformerBlock) void {
        self.attention.deinit();
        self.feedforward.deinit();
        self.allocator.free(self.norm_scale);
    }

    pub fn bitwiseLayerNorm(self: *HamiltonianTransformerBlock, input: []const u64, output: []u64) void {
        var mean_bits: u32 = 0;

        for (input) |val| {
            mean_bits += @popCount(val);
        }

        const mean = mean_bits / @as(u32, @intCast(input.len));

        for (input, 0..) |val, idx| {
            const pop_count = @popCount(val);
            const diff = if (pop_count > mean) pop_count - mean else mean - pop_count;

            const scale_factor = self.norm_scale[idx % self.norm_scale.len];
            const scaled = (val >> @as(u6, @intCast(@min(diff, 63)))) ^ (@as(u64, scale_factor) << 56);

            if (idx < output.len) {
                output[idx] = scaled;
            }
        }
    }

    pub fn forward(self: *HamiltonianTransformerBlock, input: []const u64, output: []u64, seq_len: usize) !void {
        const dim = self.attention.num_heads * self.attention.head_dim;
        const total_len = dim * seq_len;

        const norm1_output = try self.allocator.alloc(u64, total_len);
        defer self.allocator.free(norm1_output);

        self.bitwiseLayerNorm(input, norm1_output);

        const attn_output = try self.allocator.alloc(u64, total_len);
        defer self.allocator.free(attn_output);

        try self.attention.forward(norm1_output, attn_output, seq_len);

        const residual1 = try self.allocator.alloc(u64, total_len);
        defer self.allocator.free(residual1);

        for (0..total_len) |i| {
            if (i < input.len and i < attn_output.len) {
                residual1[i] = input[i] ^ attn_output[i];
            }
        }

        const norm2_output = try self.allocator.alloc(u64, total_len);
        defer self.allocator.free(norm2_output);

        self.bitwiseLayerNorm(residual1, norm2_output);

        const ff_output = try self.allocator.alloc(u64, dim);
        defer self.allocator.free(ff_output);

        for (0..seq_len) |seq_idx| {
            const seq_offset = seq_idx * dim;
            self.feedforward.forward(norm2_output[seq_offset .. seq_offset + dim], ff_output);

            for (0..dim) |d| {
                const idx = seq_offset + d;
                if (idx < output.len and d < ff_output.len and idx < residual1.len) {
                    output[idx] = residual1[idx] ^ ff_output[d];
                }
            }
        }
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var transformer_block = try HamiltonianTransformerBlock.init(allocator, 512, 8, 2048);
    defer transformer_block.deinit();

    const seq_len: usize = 32;
    const dim: usize = 512;
    const total_len = seq_len * dim;

    const input = try allocator.alloc(u64, total_len);
    defer allocator.free(input);

    var prng = std.Random.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
    const random = prng.random();

    for (input) |*val| {
        val.* = random.int(u64);
    }

    const output = try allocator.alloc(u64, total_len);
    defer allocator.free(output);

    try transformer_block.forward(input, output, seq_len);

    std.debug.print("Transformer block forward pass completed\n", .{});
}
